using GH_Net.Core.Enums; using GH_Net.Licensing; using GH_Net.Repository.Abstractions; using GH_Net.Service.Abstractions; using GH_Net.WPF.Localization; using System.Reflection; using System.Windows; using System.Windows.Media;
namespace GH_Net.WPF.ViewModels;
