{private readonly IJobRuntimeCoordinator _runtime;private readonly IZebraPrinterDevice _printer;private readonly IScannerDevice _scanner;private readonly ILicenseManager _license;private readonly LanguageService _language;private bool _disposed;public ShellViewModel(IJobRuntimeCoordinator runtime,IZebraPrinterDevice printer,IScannerDevice scanner,ILicenseManager license,LanguageService language){_runtime=runtime;_printer=printer;_scanner=scanner;_license=license;_language=language;ToggleLanguageCommand=new RelayCommand<object>(_=>_language.Toggle());_runtime.StatusChanged+=OnStatus;_printer.ConnectionStateChanged+=OnConnection;_scanner.ConnectionStateChanged+=OnConnection;_license.LicenseChanged+=OnConnection;_language.LanguageChanged+=OnConnection;}public RelayCommand<object> ToggleLanguageCommand{get;}public string AppVersion{get;}=typeof(ShellViewModel).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion??"Unknown";public string LanguageCode=>_language.CurrentCode;public string LanguageToolTip=>_language.ToggleToolTip;public bool IsPrinterConnected=>_printer.IsConnected;public bool IsScannerConnected=>_scanner.IsConnected;public bool CanOpenSettings=>_runtime.CurrentStatus!=JobStatus.Running;public string PrinterConnectionText=>IsPrinterConnected?_language.Get("Printer.Connected"):_language.Get("Printer.Disconnected");public string ScannerConnectionText=>IsScannerConnected?_language.Get("Scanner.Connected"):_language.Get("Scanner.Disconnected");public string LicenseToolTip=>$"{_language.Get("License.Open")} · {_language.Get($"License.Status.{_license.Current.Status}")}";public Brush LicenseIndicatorBrush=>(Brush)(Application.Current?.TryFindResource(!_license.Current.IsValid?"DangerBrush":"TextBrush")??Brushes.Black);public void RefreshDeviceStatus(){foreach(var n in new[]{nameof(IsPrinterConnected),nameof(IsScannerConnected),nameof(CanOpenSettings),nameof(PrinterConnectionText),nameof(ScannerConnectionText),nameof(LanguageCode),nameof(LanguageToolTip),nameof(LicenseToolTip),nameof(LicenseIndicatorBrush)})OnPropertyChanged(n);}private void OnStatus(JobStatus _)=>Dispatch();private void OnConnection(object? s,EventArgs e)=>Dispatch();private void Dispatch(){var d=Application.Current?.Dispatcher;if(d is null||d.CheckAccess())RefreshDeviceStatus();else d.BeginInvoke(RefreshDeviceStatus);}public void Dispose(){if(_disposed)return;_disposed=true;_runtime.StatusChanged-=OnStatus;_printer.ConnectionStateChanged-=OnConnection;_scanner.ConnectionStateChanged-=OnConnection;_license.LicenseChanged-=OnConnection;_language.LanguageChanged-=OnConnection;}}
